package java.util;
public class HashMap<K,V> extends AbstractMap<K,V> implements Cloneable,java.io.Serializable { static class Node<K,V> extends SimpleEntry<K,V>{final int hash;Node<K,V> next;Node(int h,K k,V v,Node<K,V> n){super(k,v);hash=h;next=n;}} Node<K,V>[] table;int count,threshold,modCount;final float loadFactor; public HashMap(){loadFactor=.75f;} public HashMap(int c){this(c,.75f);} public HashMap(int c,float f){if(c<0||f<=0||Float.isNaN(f))throw new IllegalArgumentException();loadFactor=f;int n=1;while(n<c&&n<(1<<30))n<<=1;threshold=n;} public HashMap(Map<? extends K,? extends V> m){this();putAll(m);} static int hash(Object k){int h;return k==null?0:(h=k.hashCode())^(h>>>16);} void resize(){Node<K,V>[] old=table;int oldCap=old==null?0:old.length;int cap=oldCap==0?(threshold>0?threshold:16):oldCap<<1;if(cap<=0)return;Node<K,V>[] a=(Node<K,V>[])new Node[cap];threshold=(int)(cap*loadFactor);table=a;if(old!=null)for(int i=0;i<oldCap;i++){Node<K,V> lo=null,lt=null,hi=null,ht=null;for(Node<K,V> e=old[i];e!=null;){Node<K,V> next=e.next;if((e.hash&oldCap)==0){if(lt==null)lo=e;else lt.next=e;lt=e;}else{if(ht==null)hi=e;else ht.next=e;ht=e;}e=next;}if(lt!=null){lt.next=null;a[i]=lo;}if(ht!=null){ht.next=null;a[i+oldCap]=hi;}}} Node<K,V> node(Object k){if(table==null)return null;int h=hash(k);for(Node<K,V> e=table[(table.length-1)&h];e!=null;e=e.next)if(e.hash==h&&Objects.equals(k,e.getKey()))return e;return null;} public int size(){return count;} public boolean containsKey(Object k){return node(k)!=null;} public V get(Object k){Node<K,V> e=node(k);return e==null?null:e.getValue();} public V put(K k,V v){if(table==null)resize();int h=hash(k),i=(table.length-1)&h;Node<K,V> e=table[i];if(e==null)table[i]=new Node<K,V>(h,k,v,null);else{for(;;){if(e.hash==h&&Objects.equals(k,e.getKey()))return e.setValue(v);if(e.next==null){e.next=new Node<K,V>(h,k,v,null);break;}e=e.next;}}modCount++;if(++count>threshold)resize();return null;} public V remove(Object k){if(table==null)return null;int h=hash(k),i=(table.length-1)&h;Node<K,V> p=null,e=table[i];while(e!=null){if(e.hash==h&&Objects.equals(k,e.getKey())){if(p==null)table[i]=e.next;else p.next=e.next;count--;modCount++;return e.getValue();}p=e;e=e.next;}return null;} public void clear(){if(table!=null&&count!=0){for(int i=0;i<table.length;i++)table[i]=null;count=0;modCount++;}} public Set<Entry<K,V>> entrySet(){return new AbstractSet<Entry<K,V>>(){public int size(){return count;}public void clear(){HashMap.this.clear();}public Iterator<Entry<K,V>> iterator(){return new Iterator<Entry<K,V>>(){int index,expected=modCount;Node<K,V> next,current;{advance();}void advance(){while(next==null&&table!=null&&index<table.length)next=table[index++];}public boolean hasNext(){return next!=null;}public Entry<K,V> next(){if(expected!=modCount)throw new ConcurrentModificationException();if(next==null)throw new NoSuchElementException();current=next;next=next.next;advance();return current;}public void remove(){if(current==null)throw new IllegalStateException();if(expected!=modCount)throw new ConcurrentModificationException();HashMap.this.remove(current.getKey());current=null;expected=modCount;}};}};} }
